statement_results.statement:
claim:
    ? forall X finite_set, n N+, f fn (x X) R, e1, e2 fn (k closed_range(1, n)) X, left_fn, right_fn fn (k closed_range(1, n)) R:
        forall x X:
            exist! idx closed_range(1, n) st {e1(idx) = x}
        forall x X:
            exist! idx closed_range(1, n) st {e2(idx) = x}
        left_fn = fn (idx closed_range(1, n)) R{f(e1(idx))}
        right_fn = fn (j closed_range(1, n)) R{f(e2(j))}
        =>:
            sum(1, n, left_fn) = sum(1, n, right_fn)
    $bijective(closed_range(1, n), X, e1)
    $bijective(closed_range(1, n), X, e2)
    by thm sum_over_bijective_finite_set_enumerations(sum(1, n, left_fn), sum(1, n, right_fn)) => sum(1, n, left_fn) = sum(1, n, right_fn)

